-- 20260914_exiobase_sectors.sql
--
-- ⚠️ RUN ON 14 SEPTEMBER 2026, IN FULL. DO NOT RUN IT AGAIN.
--
-- All eight blocks were executed and the four verification queries in section 8 passed. This file
-- is now a RECORD of what was done, not a script to run. It is kept executable-looking because the
-- schema it creates has to be reproducible into an empty database, and that is the only situation
-- in which any of it should be executed again.
--
-- ⚠️ SECTION 5 TRUNCATES supply_chain_registers, scope3_inventories, supplier_responses AND
-- campaign_suppliers. When it ran, those tables held one register named TEST, one scope3 row and
-- twelve campaign suppliers, all pre-launch. A second run against a live database would delete
-- every customer register, every saved Scope 3 inventory and every supplier response, with no
-- undo. If you are re-establishing this schema on an empty database, read section 5 before you
-- start and satisfy yourself the counts are what its own pre-flight query expects.
--
-- One thing HAS changed since the run: the row fingerprint below moved from 505866da... to
-- b393d1ad... when lib/emissionFactors/exiobaseSectors.json gained display_group and a groups
-- array on 14 September 2026. The live reference_data_fingerprints row was updated by a standalone
-- statement rather than by re-running any part of this file. The values seeded in sections 1 to 3
-- did not change: the generator now READS the display groups from this migration, so the file and
-- the database agree by construction.
--
-- The sector vocabulary becomes EXIOBASE's own. Three tables' worth of internal sector strings
-- become foreign keys into a seeded reference table, and the display groupings the UI needs become
-- data rather than an array in a page component.
--
-- ── WHY THIS IS A SCHEMA CHANGE AND A TRUNCATE, NOT A MIGRATION ──────────────────────────────
--
-- There WAS no customer data when this ran. One supply_chain_registers row named TEST, one
-- scope3_inventories row, twelve campaign_suppliers rows, all pre-launch. So the sector strings
-- already stored were discarded rather than mapped, and the constraints below were added outright
-- instead of backfilled behind a nullable column. Section 5 does the truncate; nothing here is
-- reversible once it runs, and nothing here may be run once a real customer row exists.
--
-- ── FIVE DECISIONS WORTH FINDING HERE RATHER THAN INFERRING ──────────────────────────────────
--
--   · ONE TABLE FOR INDUSTRIES AND PRODUCTS, NOT TWO. EXIOBASE publishes 163 industries and 200
--     products, and lib/emissionFactors/spend.ts already carries factor_type ('industry' |
--     'product') as a required discriminator on every factor record. Two tables would put that
--     discriminator in the table NAME, where a foreign key cannot see it: a column holding "an
--     EXIOBASE sector" would need two nullable FKs and a CHECK that exactly one is set, and every
--     query would union. One table with factor_type as a column keeps the discriminator in the
--     data, which is where spend.ts says it belongs.
--
--   · exio_code IS THE PRIMARY KEY, SINGLE-COLUMN, AND THAT IS SAFE BY VERIFICATION NOT BY LUCK.
--     Industry codes all begin 'i' and product codes all begin 'p'; the two sets were checked for
--     collisions and share none, so 363 codes are globally distinct. A composite (factor_type,
--     exio_code) key would be more obviously correct but would force every referencing column to
--     carry a redundant factor_type alongside it. The prefix CHECK below is what keeps the
--     single-column key honest: it makes factor_type and the code unable to disagree.
--
--   · DISPLAY GROUPS ARE A SEPARATE TABLE, DELIBERATELY. They are OUR headings for OUR dropdowns,
--     grouped on what the EXIOBASE name strings say. They are not a classification, they are not
--     derived from ISIC or NACE, and no figure is computed from them. Keeping them out of the
--     sector table and naming the table sector_display_groups is what stops the next reader
--     treating them as provenance. The table comment says so in as many words.
--
--   · isic_code AND isic_name ARE NULLABLE, AND ONLY FOR PRODUCTS. EXIOBASE's product table
--     carries no ISIC column at all. A NOT NULL with a placeholder would assert a classification
--     the publisher does not publish; the CHECK below requires them on industries and forbids
--     them on products, so absence stays a fact rather than a gap.
--
--   · THE JSONB SECTOR PATHS GET A TRIGGER, NOT A CHECK. A CHECK constraint cannot contain a
--     subquery, so it cannot ask whether a sector inside a jsonb array exists in this table. See
--     the note above section 5 for what that means and what the trigger does instead.
--
-- Source: lib/emissionFactors/exiobaseSectors.json, itself generated by
-- scripts/generate-exiobase-sectors.py from pymrio 0.6.3's bundled EXIOBASE 3 classification.
-- EXIOBASE 3 v3.8.2, DOI 10.5281/zenodo.5589597, CC BY-SA 4.0. The ShareAlike term attaches
-- obligations to anything published from this; see lib/emissionFactors/spend.ts.


-- ═══ 1. DISPLAY GROUPS ═══════════════════════════════════════════════════════════════════════

create table if not exists public.sector_display_groups (
  id            integer primary key,
  heading       text    not null unique,
  member_count  integer not null,
  created_at    timestamptz not null default now()
);

comment on table public.sector_display_groups is
  'PRESENTATION ONLY. Headings used to group the EXIOBASE industry list in ThemisIQ dropdowns so a '
  '163-item select is navigable. These are NOT a classification: they are not published by anyone, '
  'they are not derived from ISIC or NACE, they carry no methodological claim, and no emission '
  'figure is computed from them. Membership was assigned by reading what the EXIOBASE name strings '
  'say. The published classification lives in exiobase_sectors.isic_code / isic_name; if the two '
  'ever disagree, the published one is right and this one is a UI decision.';

comment on column public.sector_display_groups.member_count is
  'Industries in this group at seed time. Denormalised for review only - the authority is the count '
  'of exiobase_sectors rows carrying this heading. A disagreement means the seed is stale.';

