-- ═══ 2. THE SECTOR TABLE ═════════════════════════════════════════════════════════════════════

create table if not exists public.exiobase_sectors (
  exio_code             text    primary key,
  factor_type           text    not null check (factor_type in ('industry', 'product')),
  exio_number           integer not null,
  exio_name             text    not null,
  exio_label            text    not null,
  isic_code             text,
  isic_name             text,
  consumption_category  text    not null,
  display_group         text    references public.sector_display_groups (heading),
  product_type          text,

  -- The prefix is what lets exio_code be a single-column key without factor_type becoming
  -- decorative. A row claiming to be an industry with a 'p' code, or the reverse, cannot exist.
  constraint exiobase_sectors_code_matches_type check (
    (factor_type = 'industry' and exio_code like 'i%') or
    (factor_type = 'product'  and exio_code like 'p%')
  ),

  -- Industries carry ISIC and a display group; products carry neither and carry a product type
  -- instead. Absence is a fact about what EXIOBASE publishes, not a gap to be filled.
  constraint exiobase_sectors_industry_fields check (
    factor_type <> 'industry' or
    (isic_code is not null and isic_name is not null and display_group is not null
     and product_type is null)
  ),
  constraint exiobase_sectors_product_fields check (
    factor_type <> 'product' or
    (isic_code is null and isic_name is null and display_group is null
     and product_type is not null)
  ),

  constraint exiobase_sectors_number_per_type unique (factor_type, exio_number),
  constraint exiobase_sectors_label_unique unique (exio_label)
);

comment on table public.exiobase_sectors is
  'EXIOBASE 3 v3.8.2 sector classification: 163 industries (ixi) and 200 products (pxp). '
  'Seeded from lib/emissionFactors/exiobaseSectors.json, generated by '
  'scripts/generate-exiobase-sectors.py from pymrio 0.6.3. DOI 10.5281/zenodo.5589597, '
  'CC BY-SA 4.0 - attribution and ShareAlike apply to anything published from it. '
  'CLASSIFICATION ONLY: this table holds NO emission factors. The isic_code values are ISIC '
  'Rev. 3.1 style SECTION labels (12 distinct across 163 industries, three of them pre-aggregated '
  'multi-section buckets), consistent with the v3.8.2 readme stating the database is on NACE '
  'Rev. 1.1. They are a grouping, not a crosswalk, and cannot resolve an ISIC code back to an '
  'EXIOBASE industry.';

comment on column public.exiobase_sectors.display_group is
  'OUR heading for OUR dropdowns. Presentation only - see sector_display_groups. Null on products, '
  'which have no grouped UI today.';

create index if not exists exiobase_sectors_type_idx    on public.exiobase_sectors (factor_type);
create index if not exists exiobase_sectors_group_idx   on public.exiobase_sectors (display_group);
create index if not exists exiobase_sectors_isic_idx    on public.exiobase_sectors (isic_code);


