-- ═══ 4. GRANTS AND RLS — reference-table shape ═══════════════════════════════════════════════
--
-- Same shape as the cbam_* reference tables (20260717_cbam_reference_grants_rls.sql): world
-- readable, writable by nobody through the API. These are published classification rows, not
-- customer data, and the supply-chain wizard reads them before a session exists. A hand-run
-- CREATE TABLE grants nothing, so this block is mandatory, not tidying.

grant select on public.sector_display_groups to anon, authenticated;
grant select on public.exiobase_sectors      to anon, authenticated;
grant all    on public.sector_display_groups to service_role;
grant all    on public.exiobase_sectors      to service_role;

alter table public.sector_display_groups enable row level security;
alter table public.exiobase_sectors      enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies
                 where schemaname = 'public' and tablename = 'sector_display_groups'
                   and policyname = 'sector_display_groups_read') then
    create policy sector_display_groups_read on public.sector_display_groups
      for select to anon, authenticated using (true);
  end if;
  if not exists (select 1 from pg_policies
                 where schemaname = 'public' and tablename = 'exiobase_sectors'
                   and policyname = 'exiobase_sectors_read') then
    create policy exiobase_sectors_read on public.exiobase_sectors
      for select to anon, authenticated using (true);
  end if;
end $$;

-- No insert/update/delete policy on either table, deliberately. Seeding is done by this migration
-- as the table owner; nothing reached through the API may write a sector row.


-- ═══ 5. TRUNCATE THE TEST DATA ═══════════════════════════════════════════════════════════════
--
-- ⚠️ DESTRUCTIVE AND IRREVERSIBLE. RUN THIS ONLY WHILE THE PRE-LAUNCH TEST ROWS ARE THE ONLY ROWS.
-- Expected at the time of writing: one supply_chain_registers row named TEST, one
-- scope3_inventories row, twelve campaign_suppliers rows. Confirm those counts first:
--
--   select 'supply_chain_registers' t, count(*) from public.supply_chain_registers
--   union all select 'scope3_inventories', count(*) from public.scope3_inventories
--   union all select 'campaign_suppliers', count(*) from public.campaign_suppliers
--   union all select 'supplier_responses', count(*) from public.supplier_responses;
--
-- If any count is larger than expected, STOP: a real customer row exists and the sector strings
-- must be mapped rather than discarded.
--
-- CASCADE is required, not convenience: supplier_responses carries a foreign key to
-- campaign_suppliers, so truncating the parent without it raises. Naming supplier_responses
-- explicitly makes the loss visible in the statement rather than implied by the keyword.

truncate table
  public.supply_chain_registers,
  public.scope3_inventories,
  public.supplier_responses,
  public.campaign_suppliers
cascade;


-- ═══ 6. CONSTRAINTS THAT COULD ONLY BE ADDED ONCE THE TABLES WERE EMPTY ══════════════════════

-- 6a. scope3_inventories.sector -> a real column, so a real foreign key.
--     It held the 13-key internal vocabulary; it now holds an EXIOBASE industry code. The FK is
--     ON DELETE RESTRICT by omission (NO ACTION), which is correct: a classification row must not
--     disappear from under a saved inventory.
alter table public.scope3_inventories
  add constraint scope3_inventories_sector_fkey
  foreign key (sector) references public.exiobase_sectors (exio_code);

-- The FK alone would admit a PRODUCT code in a column that means "the company's own sector".
-- Postgres cannot express "references only rows where factor_type = 'industry'" in a foreign key,
-- so the prefix does it: industry codes begin 'i' and the table's own check keeps that true.
alter table public.scope3_inventories
  add constraint scope3_inventories_sector_is_industry
  check (sector is null or sector like 'i%');


-- ── 6b. THE JSONB PATHS. READ THIS BEFORE LOOKING FOR A CHECK CONSTRAINT. ────────────────────
--
-- ⚠️ A CHECK CONSTRAINT CANNOT DO THIS, AND NOTHING WEAKER IS WORTH ADDING.
-- Postgres forbids subqueries in CHECK, so no CHECK can ask whether a sector inside a jsonb array
-- exists in exiobase_sectors. The three things a CHECK COULD do are all worse than nothing:
--   · a hardcoded IN-list of 163 codes - a second copy of the vocabulary, drifting from the table
--     it duplicates, and the copy nobody would remember to update;
--   · a LIKE 'i%' shape test - admits 'i-made-this-up' and reads as validation;
--   · nothing at all - leaves the paths as free text, which is what they are today.
-- So this is a trigger. It is the same shape as enforce_supply_chain_entitlement() in
-- 20260913_supply_chain_registers.sql: a BEFORE INSERT OR UPDATE function that raises with a
-- custom SQLSTATE the route can match on.
--
-- PT422 is new in this schema, alongside PT402 (payment required) and the PT409/410/412/413/414
-- family. It means: the payload named a sector that is not in the classification.

create or replace function public.assert_sector_codes_exist()
returns trigger
language plpgsql
security definer
set search_path to 'public'
as $$
declare
  bad text;
begin
  if tg_table_name = 'supply_chain_registers' then
    -- Every element of the suppliers array must carry a sector that exists and is an industry.
    -- A null or absent sector is rejected too: the CSV import path used to default it silently,
    -- and an absent sector reaching storage is the defect that made this necessary.
    -- ⚠️ coalesce, NOT a bare s.sector. string_agg SKIPS NULLS, so aggregating the raw column
    -- would leave `bad` null when every offending row had a MISSING sector - the exact case this
    -- check exists for - and the trigger would raise nothing at all.
    select string_agg(distinct coalesce(s.sector, '(missing)'), ', ')
      into bad
      from jsonb_to_recordset(new.suppliers) as s(sector text)
     where s.sector is null
        or not exists (select 1 from public.exiobase_sectors e
                        where e.exio_code = s.sector and e.factor_type = 'industry');
    if bad is not null then
      raise exception 'Unknown sector code(s) in suppliers: %', bad using errcode = 'PT422';
    end if;
    return new;
  end if;

  if tg_table_name = 'scope3_inventories' then
    -- Two known paths carry a sector inside cat_data. Both are optional; both must be valid when
    -- present. Listed explicitly rather than scanned, so a new sector-bearing path has to be added
    -- here consciously instead of being silently unvalidated.
    select string_agg(v, ', ')
      into bad
      from (values (new.cat_data #>> '{cat1,supplier_sector}'),
                   (new.cat_data #>> '{cat15,portfolio_sector}')) as t(v)
     where v is not null
       and not exists (select 1 from public.exiobase_sectors e
                        where e.exio_code = v and e.factor_type = 'industry');
    if bad is not null then
      raise exception 'Unknown sector code(s) in cat_data: %', bad using errcode = 'PT422';
    end if;
    return new;
  end if;

  return new;
end $$;

comment on function public.assert_sector_codes_exist() is
  'Validates sector codes held inside jsonb, which no CHECK constraint can do: CHECK forbids '
  'subqueries, so membership in exiobase_sectors is unreachable from one. Covers '
  'supply_chain_registers.suppliers[].sector and scope3_inventories.cat_data cat1.supplier_sector '
  'and cat15.portfolio_sector. Raises SQLSTATE PT422.';

drop trigger if exists trg_supply_chain_registers_sectors on public.supply_chain_registers;
create trigger trg_supply_chain_registers_sectors
  before insert or update on public.supply_chain_registers
  for each row execute function public.assert_sector_codes_exist();

drop trigger if exists trg_scope3_inventories_sectors on public.scope3_inventories;
create trigger trg_scope3_inventories_sectors
  before insert or update on public.scope3_inventories
  for each row execute function public.assert_sector_codes_exist();


-- ═══ 7. KEEPING THE SEED IN STEP WITH THE JSON ═══════════════════════════════════════════════
--
-- The JSON is fingerprinted by lib/emissionFactors/exiobaseSectors.test.ts and that test runs in
-- `npm run build`. This table is not, and cannot be: the build has no database connection, so no
-- vitest assertion can see these rows. The fingerprint is recorded here so the comparison is
-- possible at all, by a human or by a script that connects.

create table if not exists public.reference_data_fingerprints (
  dataset      text primary key,
  fingerprint  text not null,
  source_file  text not null,
  seeded_at    timestamptz not null default now()
);

grant select on public.reference_data_fingerprints to authenticated;
grant all    on public.reference_data_fingerprints to service_role;
alter table public.reference_data_fingerprints enable row level security;

do $$
begin
  if not exists (select 1 from pg_policies
                 where schemaname = 'public' and tablename = 'reference_data_fingerprints'
                   and policyname = 'reference_data_fingerprints_read') then
    create policy reference_data_fingerprints_read on public.reference_data_fingerprints
      for select to authenticated using (true);
  end if;
end $$;

comment on table public.reference_data_fingerprints is
  'What this database was seeded FROM, for reference datasets whose authority is a file in the '
  'repo. The fingerprint is the same sha256 the repo test pins, so a divergence between the file '
  'and the seeded rows is detectable by comparing two strings. Nothing computes this automatically: '
  'the build cannot reach the database. See the note below this table in the migration.';

insert into public.reference_data_fingerprints (dataset, fingerprint, source_file) values
  ('exiobase_sectors',
   'b393d1ad7d4966cd0ddd7c29379c98b362ab9bed01be7e98afd53226647e3341',
   'lib/emissionFactors/exiobaseSectors.json')
on conflict (dataset) do update
  set fingerprint = excluded.fingerprint,
      source_file = excluded.source_file,
      seeded_at   = now();


